import math

def get_sum_of_proper_divisors(n):
    if n <= 1:
        return 0
    sum_divs = 1
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            sum_divs += i
            if i * i != n:
                sum_divs += n // i
    return sum_divs

def amicable_numbers_sum(limit):
    total_amicable_sum = 0
    amicable_numbers_found = set()

    for a in range(1, limit):
        if a in amicable_numbers_found:
            continue

        b = get_sum_of_proper_divisors(a)

        if b > a and b < limit:
            c = get_sum_of_proper_divisors(b)
            if c == a:
                total_amicable_sum += a + b
                amicable_numbers_found.add(a)
                amicable_numbers_found.add(b)

    return total_amicable_sum

