def magic_square_test(my_matrix):
    n = len(my_matrix)

    if n == 0:
        return True

    for row in my_matrix:
        if len(row) != n:
            return False

    magic_sum = sum(my_matrix[0])

    for row in my_matrix:
        if sum(row) != magic_sum:
            return False

    for col_idx in range(n):
        current_col_sum = 0
        for row_idx in range(n):
            current_col_sum += my_matrix[row_idx][col_idx]
        if current_col_sum != magic_sum:
            return False

    main_diag_sum = 0
    for i in range(n):
        main_diag_sum += my_matrix[i][i]
    if main_diag_sum != magic_sum:
        return False

    anti_diag_sum = 0
    for i in range(n):
        anti_diag_sum += my_matrix[i][n - 1 - i]
    if anti_diag_sum != magic_sum:
        return False

    return True

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

