def max_occurrences(nums):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    if not counts:
        return (None, 0)

    max_item = None
    max_count = -1

    for item, count in counts.items():
        if count > max_count:
            max_count = count
            max_item = item

    return (max_item, max_count)

