def get_total_number_of_sequences(m, n):
    if n <= 0 or m <= 0:
        return 0

    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for j in range(1, m + 1):
        dp[1][j] = 1

    for i in range(2, n + 1):
        prefix_sum_prev = [0] * (m + 1)
        for k_val in range(1, m + 1):
            prefix_sum_prev[k_val] = prefix_sum_prev[k_val - 1] + dp[i - 1][k_val]

        for j in range(1, m + 1):
            limit_prev_val = j // 2

            if limit_prev_val >= 1:
                dp[i][j] = prefix_sum_prev[limit_prev_val]

    total_sequences = 0
    for j in range(1, m + 1):
        total_sequences += dp[n][j]

    return total_sequences

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

