def max_sum_increasing_subseq(a, n, index, k):
    dp = list(a) 

    for i in range(n):
        for j in range(i):
            if a[i] > a[j]:
                dp[i] = max(dp[i], a[i] + dp[j])

    max_prev_sum = 0

    for j in range(index + 1):
        if a[j] < a[k]:
            max_prev_sum = max(max_prev_sum, dp[j])

    return max_prev_sum + a[k]

