def _rotate_and_fix(arr, out_of_place_idx, current_idx):
    val = arr[current_idx]
    for k in range(current_idx, out_of_place_idx, -1):
        arr[k] = arr[k - 1]
    arr[out_of_place_idx] = val

def right_rotate(arr, n, out_of_place=None, cur=None):
    if n == 0:
        return []

    out_of_place_tracker = -1

    for i in range(n):
        if out_of_place_tracker != -1:
            if arr[out_of_place_tracker] >= 0 and out_of_place_tracker % 2 == 0 and arr[i] < 0:
                _rotate_and_fix(arr, out_of_place_tracker, i)
                out_of_place_tracker = -1 if i - out_of_place_tracker == 1 else out_of_place_tracker + 2

            elif arr[out_of_place_tracker] < 0 and out_of_place_tracker % 2 == 1 and arr[i] >= 0:
                _rotate_and_fix(arr, out_of_place_tracker, i)
                out_of_place_tracker = -1 if i - out_of_place_tracker == 1 else out_of_place_tracker + 2

        if out_of_place_tracker == -1:
            if i % 2 == 0 and arr[i] >= 0:
                out_of_place_tracker = i
            elif i % 2 == 1 and arr[i] < 0:
                out_of_place_tracker = i

    return arr

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, right_rotate([-5, -2, 5, 2, 4, 7, 1, 8, 0, -8], 10), [-5, 5, -2, 2, -8, 4, 7, 1, 8, 0])
    check(2, right_rotate([-1, 2, -3, 4, -5, 6, -7, 8, -9], 9), [-1, 2, -3, 4, -5, 6, -7, 8, -9])
    check(3, right_rotate([1, 2, 3, -1, -2, -3], 6), [-1, 1, -2, 2, -3, 3])
    check(4, right_rotate([-1, -2, -3, 1, 2, 3], 6), [-1, 1, -2, 2, -3, 3])
    check(5, right_rotate([1, 2, 3, 4, 5], 5), [1, 2, 3, 4, 5]) 
    check(6, right_rotate([1, -2, 3, -4, 5, -6], 6), [-2, 1, -4, 3, -6, 5])
    check(7, right_rotate([0, 1, 0, -1, 0, -2], 6), [-1, 0, -2, 1, 0, 0])
    check(8, right_rotate([-10, 20, -30, 40], 4), [-10, 20, -30, 40])
    check(9, right_rotate([20, -10, 40, -30], 4), [-10, 20, -30, 40])
