def ncr_modp(n, r, p):
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r

    C = [0 for i in range(r + 1)]
    C[0] = 1

    for i in range(1, n + 1):
        for j in range(min(i, r), 0, -1):
            C[j] = (C[j] + C[j - 1]) % p
    return C[r]

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, ncr_modp(10, 2, 13), 6)
    check(2, ncr_modp(5, 2, 7), 3)
    check(3, ncr_modp(7, 3, 5), 0)
    check(4, ncr_modp(10, 0, 13), 1)
    check(5, ncr_modp(5, 5, 13), 1)
