def max_Product(arr):
    arr_len = len(arr)
    if arr_len < 2:
        return None

    x = arr[0]
    y = arr[1]

    for i in range(arr_len):
        for j in range(i + 1, arr_len):
            if arr[i] * arr[j] > x * y:
                x = arr[i]
                y = arr[j]

    return (x, y)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
