    check(3, max_Product([-10, -5, 1, 2, 3]), (-10, -5))
    check(4, max_Product([0, 0, 0, 0]), (0, 0))
    check(5, max_Product([5]), None)
    check(6, max_Product([10, 20]), (10, 20))
