    check(5, sum_gp(3, 2, 4), 15)
    check(6, sum_gp(5, 0, 2), 0) # n=0 terms
    check(7, sum_gp(0, 5, 2), 0) # a=0
    check(8, sum_gp(5, 3, 0), 5) # r=0 (series: 5, 0, 0. Sum = 5)
